PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_version VALUES(1,strftime('%Y-%m-%dT%H:%M:%SZ','now'));
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, kind TEXT NOT NULL, url TEXT NOT NULL, retrieved_at TEXT NOT NULL, published_at TEXT, sha256 TEXT NOT NULL, raw_json TEXT NOT NULL, UNIQUE(url,sha256));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL,codename TEXT NOT NULL UNIQUE,identity_status TEXT NOT NULL CHECK(identity_status IN ('unresolved','imported','reviewed')),source_id TEXT REFERENCES sources(id),raw_heading TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS formulations(id INTEGER PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),component TEXT NOT NULL,amount TEXT,source_id TEXT NOT NULL REFERENCES sources(id),review_status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS vial_sizes(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),label TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(id),UNIQUE(product_id,label));
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,product_id TEXT REFERENCES products(id),lot TEXT,source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS lab_results(id TEXT PRIMARY KEY,product_id TEXT REFERENCES products(id),size_id TEXT REFERENCES vial_sizes(id),batch_id TEXT REFERENCES batches(id),source_id TEXT NOT NULL REFERENCES sources(id),lab TEXT,report_date TEXT,search_code TEXT,identity TEXT,purity TEXT,measured_content TEXT,attribution TEXT NOT NULL CHECK(attribution IN ('gloformulas','supplier','unverified','missing')),verification_status TEXT NOT NULL DEFAULT 'pending',raw_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),category TEXT NOT NULL CHECK(category IN ('uses','concurrent_use','precautions','insufficient_evidence')),claim TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(id),publication_date TEXT,quality TEXT NOT NULL CHECK(quality IN ('unassessed','label','systematic_review','human_trial','observational','preclinical','other')),review_status TEXT NOT NULL CHECK(review_status IN ('pending','approved','rejected')),reviewer TEXT,reviewed_at TEXT,UNIQUE(product_id,category,claim,source_id));
CREATE TABLE IF NOT EXISTS guide_blocks(id TEXT PRIMARY KEY,product_id TEXT REFERENCES products(id),source_id TEXT NOT NULL REFERENCES sources(id),tab_id TEXT NOT NULL,start_index INTEGER,end_index INTEGER,raw_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS flags(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,code TEXT NOT NULL,detail TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS catalog_snapshots(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),observed_at TEXT NOT NULL,complete INTEGER NOT NULL CHECK(complete IN (0,1)),raw_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalog_changes(id TEXT PRIMARY KEY,snapshot_id TEXT NOT NULL REFERENCES catalog_snapshots(id),product_key TEXT NOT NULL,kind TEXT NOT NULL,before_json TEXT,after_json TEXT);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,summary_json TEXT);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY,created_at TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,detail_json TEXT NOT NULL);
